def solve(nums):
    a = list(nums)
    n = len(a)
    # Find pivot: rightmost i with a[i] < a[i+1]
    i = n - 2
    while i >= 0 and a[i] >= a[i + 1]:
        i -= 1
    if i >= 0:
        # Find rightmost j with a[j] > a[i], swap
        j = n - 1
        while a[j] <= a[i]:
            j -= 1
        a[i], a[j] = a[j], a[i]
    # Reverse suffix
    l, r = i + 1, n - 1
    while l < r:
        a[l], a[r] = a[r], a[l]
        l += 1
        r -= 1
    if i < 0:
        # Last permutation: return sorted list
        return sorted(a)
    return a

